INSERT INTO "runbooks" VALUES(9951,'Retry policy standard','All cross-service calls MUST configure retries: set config key ''<downstream>_retry_max_attempts'' to 3 (exponential backoff is applied automatically). A value of 0 means a single downstream timeout permanently fails the request.');
INSERT INTO "runbooks" VALUES(9952,'Deployment policy','Every production deploy must first succeed on staging (same version). Tier-1 services (storefront-web, api-gateway, checkout, payments) must additionally canary in production at <=25% (deploy_service with canary_percent<=25) and promote with promote_canary only after verification. Use rollback_deployment for emergency rollback; rollbacks are exempt from the staging-first rule.');
INSERT INTO "runbooks" VALUES(9953,'Search caching','cache_enabled=true is required in production for the search service; the query cache absorbs ~75% of index load. TTL standard is 300s.');
INSERT INTO "runbooks" VALUES(9954,'Incident response','1) acknowledge the firing alert 2) mitigate (rollback or feature-flag kill switch) 3) verify metric recovery 4) resolve the alert 5) resolve the incident 6) post an update in #incidents 7) for sev1: file a postmortem ticket (type ''postmortem'').');
INSERT INTO "runbooks" VALUES(9955,'API deprecation','Deprecate the endpoint first (status ''deprecated'') and deploy that change. Then shift traffic to the replacement in stages of at most 50 percentage points per step. Only when the legacy endpoint serves 0% traffic may it be retired (status ''retired''); CI blocks retirement of endpoints still serving traffic.');
INSERT INTO "runbooks" VALUES(9956,'Security response','Patch the vulnerable dependency, deploy staging then production, verify the scanner shows the finding remediated, post an audit summary to #security referencing the CVE id, and close the security ticket.');
INSERT INTO "runbooks" VALUES(9957,'Feature flags','New user-facing features ship dark behind a flag (define the flag via a ''flag'' PR change; it is created disabled in both environments at merge). The guarded code must be deployed to production BEFORE the flag is enabled there. Initial production rollout must not exceed 10%. Flags are runtime toggles: set_feature_flag needs no deploy.');
INSERT INTO "runbooks" VALUES(9958,'Flaky tests','Diagnose from CI history (list_ci_runs). Fix the root cause via a PR with a test_fix change (action ''fix''); quarantine (action ''quarantine'') is a last resort and does not close the ticket. After merging, prove stability with 3 consecutive green main-branch runs: run_ci(service=...).');
