INSERT INTO "tickets" VALUES(9101,'ENG-2101','bug','Reduce payments error rate breaching SLO','payments error_rate_pct has been breaching its 1.0% SLO for two days (alert 9601). Investigate production logs to find the root cause, fix it through the standard PR -> CI -> merge -> staged deployment workflow (see the ''Deployment policy'' runbook: staging first, tier-1 services canary at <=25% then promote), confirm the metric recovered, resolve the alert, and close this ticket.','open','high','','payments');
INSERT INTO "tickets" VALUES(9102,'ENG-2102','bug','Search p99 latency exceeds SLO','search latency_p99_ms is 850ms against a 300ms SLO (alert 9602). Find the root cause (see logs and the ''Search caching'' runbook), ship the fix staging-first, confirm recovery, resolve the alert, and close this ticket.','open','high','','search');
INSERT INTO "tickets" VALUES(9103,'ENG-2201','feature','Ship express checkout behind a feature flag at 10% production rollout','Implement the express_checkout module in the checkout service gated behind a NEW feature flag named ''express_checkout'' (define the flag in the same PR with a ''flag'' change). Per the ''Feature flags'' runbook the code must be deployed to production (staging first, canary then promote — checkout is tier 1) BEFORE the flag is enabled. Then enable the flag in production at a 10% rollout. Close this ticket when done.','open','medium','','checkout');
INSERT INTO "tickets" VALUES(9104,'ENG-2202','incident','Disable instant_refunds and resolve checkout error spike','Incident 9702 (sev2): checkout error_rate_pct jumped to 5.5% right after the instant_refunds flag ramped to 100% in production. Per the ''Incident response'' runbook: acknowledge the alert, kill-switch the flag in production (leave staging as-is), verify the metric recovered, resolve the alert and the incident, post an update in #incidents mentioning instant_refunds, and close this ticket.','open','critical','','checkout');
INSERT INTO "tickets" VALUES(9105,'SEC-901','security','Patch CVE-2026-31337 in libpayproc (payments)','Security scanner reports libpayproc 2.3.1 in payments is vulnerable to CVE-2026-31337 (critical). Upgrade the dependency to the fixed version 2.4.0 via the standard workflow, deploy staging-first (payments is tier 1: canary then promote), confirm the scanner shows the vulnerability remediated, post an audit summary to #security referencing the CVE, and close this ticket.','open','critical','','payments');
INSERT INTO "tickets" VALUES(9106,'SEC-902','security','Retire exposed /internal/debug endpoint on api-gateway','A security review found the unauthenticated /internal/debug endpoint still active in production on api-gateway. Retire it via an endpoint PR change and deploy staging-first (api-gateway is tier 1: canary then promote). Close this ticket.','open','high','','api-gateway');
INSERT INTO "tickets" VALUES(9107,'ENG-2301','feature','Loyalty points across catalog, checkout, and storefront-web','Ship the loyalty-points feature: add module ''loyalty_accrual'' to catalog, module ''loyalty_redeem'' to checkout, and module ''loyalty_widget'' to storefront-web (one PR per service). Deployment order matters: catalog must reach production before checkout, and checkout before storefront-web. Every production deploy is staging-first; checkout and storefront-web are tier 1 (canary <=25% then promote). Close this ticket when all three are live.','open','medium','','');
INSERT INTO "tickets" VALUES(9108,'ENG-2302','feature','Migrate /v1/orders traffic to /v2/orders and retire v1','Per the ''API deprecation'' runbook: mark /v1/orders deprecated (endpoint PR change) and deploy that to production first; then shift traffic from /v1/orders to /v2/orders in stages of at most 50 percentage points per step until /v2/orders serves 100% and /v1/orders serves 0%; only then retire /v1/orders with a second PR and deploy it. api-gateway is tier 1 (staging first, canary then promote). Close this ticket when v1 is retired in production.','open','medium','','api-gateway');
INSERT INTO "tickets" VALUES(9109,'ENG-2401','bug','Fix flaky test_checkout_idempotency; prove 3 consecutive green main runs','checkout CI is unreliable: test_checkout_idempotency fails intermittently (see CI history). Fix the root cause via a PR with a test_fix change (action ''fix'' — do NOT just quarantine it), merge it, then demonstrate stability with at least 3 consecutive green main-branch CI runs (run_ci with service=''checkout''). Close this ticket.','open','high','','checkout');
INSERT INTO "tickets" VALUES(9110,'ENG-2402','incident','SEV1: roll back api-gateway v5.1.0 and file postmortem','Incident 9701 (sev1): api-gateway p99 latency jumped to ~1030ms right after v5.1.0 was promoted in production. Per the ''Incident response'' runbook: acknowledge the alert, roll back the production deployment, verify the metric recovered, resolve the alert and the incident, create a postmortem ticket (type ''postmortem'', service api-gateway, mention v5.1.0), post an update in #incidents, and close this ticket.','open','critical','','api-gateway');
